// friday13.cs — Friday the 13th explorer (proleptic Gregorian calendar)

// Find the earliest Friday the 13th starting from 0001-01-01
var earliest = Enumerable.Range(1, 12)
    .Select(m => new DateTime(1, m, 13))
    .First(d => d.DayOfWeek == DayOfWeek.Friday);

Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd} ({earliest:dddd})");

// Count Friday the 13ths in a full 400-year cycle (the Gregorian calendar repeats every 400 years)
int count = 0;
var byMonth = new int[12];

for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        if (new DateTime(year, month, 13).DayOfWeek == DayOfWeek.Friday)
        {
            count++;
            byMonth[month - 1]++;
        }
    }
}

Console.WriteLine($"\nFriday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");
Console.WriteLine();
Console.WriteLine("Distribution by month:");
for (int i = 0; i < 12; i++)
{
    var bar = new string('█', byMonth[i]);
    Console.WriteLine($"  {new DateTime(1, i + 1, 1):MMM}: {byMonth[i],3}  {bar}");
}

